<?php
declare(strict_types=1);
function interface_defaults(): array {return ['palette'=>null,'version'=>1,'home'=>'decouvrir','density'=>'comfortable','banner'=>'full','text'=>'normal','hints'=>true,'shortcuts'=>['prospection','musique','demandes','planning'],'hidden'=>[],'moduleOrder'=>[],'hintCount'=>0];}
function interface_validate(mixed $v): array {
    $routes=['decouvrir','accueil','parcours','prospection','demandes','contacts','veille','sources','programmation','atelier-partage','modules','atelier-creation','bibliotheque','exercices','improvisation','spectacles','productions','planning','agenda','equipe','troupe','collectif','contribuer','ressources','aides','materiel','communication','demarrer','qualite'];
    if(!is_array($v)||($v['version']??null)!==1||!in_array($v['home']??'',$routes,true)||!in_array($v['density']??'',['comfortable','compact'],true)||!in_array($v['banner']??'',['full','compact','hidden'],true)||!in_array($v['text']??'',['normal','large'],true)||!is_bool($v['hints']??null))fail(422,'Réglages de présentation invalides.');
    foreach(['shortcuts','hidden'] as $key){$rows=$v[$key]??null;if(!is_array($rows)||!array_is_list($rows)||count($rows)>($key==='shortcuts'?6:count($routes)))fail(422,'Liste de rubriques invalide.');foreach($rows as $r)if(!is_string($r)||!in_array($r,$routes,true))fail(422,'Rubrique inconnue.');if(count(array_unique($rows))!==count($rows))fail(422,'Rubrique en double.');}
    $hintCount=$v['hintCount']??0;if(!is_int($hintCount)||$hintCount<0||$hintCount>50)fail(422,'Progression des conseils invalide.');
    $hintCount=$v['hintCount']??0;if(!is_int($hintCount)||$hintCount<0||$hintCount>50)fail(422,'Progression des conseils invalide.');
    $order=$v['moduleOrder']??[];if(!is_array($order)||!array_is_list($order)||count($order)>80)fail(422,'Ordre des modules invalide.');foreach($order as $id)if(!is_string($id)||!preg_match('/^[a-z0-9-]{2,40}$/D',$id))fail(422,'Module invalide.');if(count(array_unique($order))!==count($order))fail(422,'Module en double.');
    if(in_array($v['home'],$v['hidden'],true))fail(422,'La page de démarrage doit rester visible.');if(isset($v['palette'])&&(!is_array($v['palette'])||!is_int($v['palette']['hue']??null)||$v['palette']['hue']<0||$v['palette']['hue']>359))fail(422,'Couleur personnelle invalide.');return ['palette'=>isset($v['palette'])?['hue'=>$v['palette']['hue']]:null,'version'=>1,'home'=>$v['home'],'density'=>$v['density'],'banner'=>$v['banner'],'text'=>$v['text'],'hints'=>$v['hints'],'shortcuts'=>array_values(array_diff($v['shortcuts'],$v['hidden'])),'hidden'=>$v['hidden'],'moduleOrder'=>$order,'hintCount'=>$hintCount];
}
function interface_data(string $actor): array {$row=query('SELECT settings,updated_at FROM atelier_interface_preferences WHERE account_id=?',[$actor])->fetch();$settings=interface_defaults();if($row)try{$settings=interface_validate(json_decode($row['settings'],true,32,JSON_THROW_ON_ERROR));}catch(Throwable){}return ['settings'=>$settings,'scope'=>hash('sha256','interface|'.$actor),'updatedAt'=>$row?(int)$row['updated_at']:null];}
function interface_save(string $actor,array $v): array {if(!is_string($v['scope']??null)||!hash_equals(hash('sha256','interface|'.$actor),$v['scope']))fail(409,'Le compte a changé. Rechargez vos préférences.');$settings=interface_validate($v['settings']??null);$json=json_encode($settings,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$now=(int)round(microtime(true)*1000);$mysql=db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql';$sql=$mysql?'INSERT INTO atelier_interface_preferences(account_id,settings,updated_at) VALUES(?,?,?) ON DUPLICATE KEY UPDATE settings=?,updated_at=?':'INSERT INTO atelier_interface_preferences(account_id,settings,updated_at) VALUES(?,?,?) ON CONFLICT(account_id) DO UPDATE SET settings=excluded.settings,updated_at=excluded.updated_at';query($sql,$mysql?[$actor,$json,$now,$json,$now]:[$actor,$json,$now]);return interface_data($actor);}
